    // ─────────── فصل ۱: پسر برهمن ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Brahmin's Son", titlePersian = "پسر برهمن",
        paragraphs = listOf(
            StoryParagraph("In the shade of the house, in the sunshine of the riverbank near the boats, in the shade of the sal-tree forest, Siddhartha grew up, the handsome son of the Brahmin.", "در سایه خانه، در آفتاب کنار رود نزدیک قایق‌ها، در سایه جنگل درختان سال، سیدارتا بزرگ شد، پسر زیبای برهمن."),
            StoryParagraph("The sun browned his slender shoulders on the riverbank, while bathing, while performing the sacred ablutions, while making his offerings to the gods.", "خورشید شانه‌های باریکش را در کنار رودخانه برنزه کرد، هنگام شنا کردن، هنگام به جای آوردن وضوهای مقدس، هنگام قربانی کردن برای خدایان."),
            StoryParagraph("Shadows flowed into his black eyes during the mango grove, during the games of the boys, during the songs of his mother.", "سایه‌ها در چشمان سیاهش جاری شدند، در بیشه انبه، در بازی‌های پسران، در آوازهای مادرش."),
            StoryParagraph("Siddhartha had already been taking part in the conversations of the wise for a long time, had already been practicing the art of contemplation with Govinda, had already learned the ways of Brahman.", "سیدارتا مدت‌ها بود در گفتگوهای دانایان شرکت می‌کرد، مدت‌ها بود با گویندا هنر مراقبه را تمرین می‌کرد، مدت‌ها بود راه‌های برهمن را آموخته بود."),
            StoryParagraph("His father had already noticed him growing into a great sage and priest, a prince among the Brahmins.", "پدرش از قبل متوجه شده بود که او در حال رشد به حکیمی بزرگ و کشیشی، شاهزاده‌ای میان برهمنان."),
            StoryParagraph("Joy leaped in his father's heart at the sight of his son, the intelligent boy, the thirster after knowledge.", "شادی در قلب پدرش هنگام دیدن پسرش جهید، پسر باهوش، تشنه‌دانش."),
            StoryParagraph("But Siddhartha did not bring joy to himself, did not bring pleasure to himself.", "اما سیدارتا برای خودش شادی نمی‌آورد، برای خودش لذت نمی‌آورد."),
            StoryParagraph("He walked about with the most beautiful of all the girls in the town, and his gaze was sad when it met the gaze of a woman.", "با زیباترین دختران شهر قدم می‌زد و نگاهش اندوهناک بود وقتی به نگاه زنی می‌رسید."),
            StoryParagraph("He walked in the shade of the mango grove, with the noble, graceful Govinda, his friend, the son of a Brahmin like himself.", "در سایه بیشه انبه راه می‌رفت، با گویندای نجیب و دلنشین، دوستش، پسر برهمنی چون خودش."),
            StoryParagraph("He walked with Govinda, and they had both learned the way of the Buddha, and yet they had not found peace.", "با گویندا راه می‌رفت و هر دو راه بودا را آموخته بودند و با این حال آرامش نیافته بودند."),
            StoryParagraph("But Siddhartha, even though he was so learned, even though he was so pious, even though he was so contemplative, still felt this doubt, this thirst, this restlessness.", "اما سیدارتا، هرچند اینقدر عالم بود، اینقدر پارسا، اینقدر تأمل‌گر، هنوز این شک را حس می‌کرد، این تشنگی، این بی‌قراری."),
            StoryParagraph("He had begun to feel that the love of his father and mother, and the love of his friend Govinda, would not make him happy forever, would not bring him peace, would not satisfy him.", "شروع کرده بود به حس کردن اینکه عشق پدر و مادرش و عشق دوستش گویندا برای همیشه خوشحالش نمی‌کند، آرامش نمی‌آورد، راضی‌اش نمی‌کند."),
            StoryParagraph("He had begun to suspect that his venerable father and his other teachers, that the wise Brahmins, had already imparted to him the most and best part of their wisdom, had already poured their fullness into his waiting vessel.", "شروع کرده بود به شک کردن که پدر محترمش و دیگر معلمانش، آن برهمنان دانا، از قبل بیشتر و بهترین بخش خردشان را به او منتقل کرده بودند، پُری‌شان را در ظرف منتظرش ریخته بودند."),
            StoryParagraph("But the vessel was not full, the mind was not satisfied, the soul was not at peace, the heart was not quiet.", "اما ظرف پر نبود، ذهن راضی نبود، روح در آرامش نبود، قلب ساکت نبود."),
            StoryParagraph("The ablutions were good, but they were water, they did not wash off the sin, they did not heal the spirit's thirst, they did not allay the heart's fear.", "وضوها خوب بودند، اما آب بودند، گناه را نمی‌شستند، تشنگی روح را شفا نمی‌دادند، ترس قلب را تسکین نمی‌دادند."),
            StoryParagraph("The sacrifices and the invocation of the gods were excellent, but was that all?", "قربانی‌ها و خواندن خدایان ممتاز بودند، اما همین همه بود؟"),
            StoryParagraph("Did the sacrifices give happiness? And what about the gods? Was it really Prajapati who had created the world?", "قربانی‌ها شادی می‌دادند؟ و خدایان چه؟ واقعاً پراجاپاتی جهان را آفریده بود؟"),
            StoryParagraph("Was it not Atman, he, the only one, the all-one?", "آیا آتمان نبود، او، یکتا، همه-یک؟"),
            StoryParagraph("Were the gods not creations, created like me and you, subject to time, impermanent?", "آیا خدایان آفریده نبودند، آفریده شده چون من و تو، تابع زمان، ناپایدار؟"),
            StoryParagraph("Was it therefore right to sacrifice to the gods, to make offerings, to pray to them?", "پس آیا درست بود قربانی کردن برای خدایان، نذر کردن، دعا کردن به آنان؟"),
            StoryParagraph("Whom else did one have to sacrifice to, whom else did one have to worship but him, the only one, Atman?", "برای که دیگری باید قربانی کرد، که دیگری را باید پرستید جز او، یکتا، آتمان؟"),
            StoryParagraph("And where, where was Atman to be found, where did he dwell, where did his eternal heart beat, where else but in one's own self, in its innermost, in the indestructible, which everyone bore within himself?", "و کجا، کجا آتمان یافت می‌شد، کجا سکنی داشت، قلب ابدی‌اش کجا می‌تپید، کجا جز در خودِ خویش، در باطنش، در تخریب‌ناپذیر، که هر کس در خودش حمل می‌کرد؟"),
            StoryParagraph("But where, where was this self, this innermost, this ultimate?", "اما کجا، کجا این خود بود، این باطن، این نهایی؟"),
            StoryParagraph("It was not flesh and bone, it was not thought or consciousness.", "نه گوشت و استخوان بود، نه فکر و آگاهی."),
            StoryParagraph("So where, where was it?", "پس کجا، کجا بود؟"),
            StoryParagraph("There was no other way to find it, no other way to become one with it.", "هیچ راه دیگری برای یافتنش نبود، هیچ راه دیگری برای یکی شدن با آن."),
            StoryParagraph("And yet, all the Brahmins, and all the holy books, and all the sacrifices, and all the prayers, knew this way, knew the path.", "و با این حال، همه برهمنان و همه کتاب‌های مقدس و همه قربانی‌ها و همه دعاها این راه را می‌شناختند، این مسیر را."),
            StoryParagraph("Siddhartha did not know it; he who was closest to the Brahman, he who was the Brahmin among the Brahmins, did not know it.", "سیدارتا نمی‌شناختش؛ او که نزدیک‌ترین به برهمن بود، او که برهمن میان برهمنان بود، نمی‌شناختش."),
            StoryParagraph("One day, Siddhartha said to Govinda, 'Tomorrow I will join the Samanas. I will become a wandering ascetic.'", "یک روز سیدارتا به گویندا گفت: «فردا به ساماناها می‌پیوندم. زاهد سرگردانی می‌شوم.»"),
            StoryParagraph("Govinda turned pale when he heard these words and read the decision in the motionless face of his friend, unstoppable like the arrow shot from the bow.", "گویندا وقتی این کلمات را شنید رنگ‌پریده شد و تصمیم را در چهره بی‌حرکت دوستش خواند، متوقف‌ناشدنی چون تیری که از کمان رها شده."),
            StoryParagraph("At once, and as if by a stroke of lightning, Govinda understood the decision of Siddhartha.", "بلافاصله، و گویی با ضربه‌ای از آذرخش، گویندا تصمیم سیدارتا را فهمید."),
            StoryParagraph("And his face grew pale as he saw his friend walk away, and his eyes grew dark with sadness.", "و چهره‌اش رنگ‌پریده شد همانطور که می‌دید دوستش دور می‌شود و چشمانش با اندوه تیره شدند."),
            StoryParagraph("'Siddhartha,' he said, 'will your father permit it?'", "گفت: «سیدارتا، پدرت اجازه می‌دهد؟»"),
            StoryParagraph("Siddhartha looked at Govinda, as awakened from a dream; and yes, in the flash of a moment, he pierced the soul of Govinda with his look.", "سیدارتا به گویندا نگاه کرد، گویی از خواب بیدار شده؛ و آری، در برق یک لحظه، روح گویندا را با نگاهش سوراخ کرد."),
            StoryParagraph("'Do not waste words, Govinda,' he said quietly. 'Tomorrow at daybreak, I will begin the life of the Samanas. Do not speak of it again.'", "آرام گفت: «کلمات را هدر نده، گویندا. فردا هنگام سپیده، زندگی ساماناها را آغاز می‌کنم. دیگر از آن صحبت نکن.»"),
            StoryParagraph("And Govinda, speechless, returned to his father's house, and Siddhartha went to his father's house, and neither slept that night.", "و گویندا، بی‌سخن، به خانه پدرش بازگشت و سیدارتا به خانه پدرش رفت و هیچ‌کدام آن شب نخوابیدند."),
            StoryParagraph("At midnight, Siddhartha went to his father, and stood before him, and said, 'With your permission, Father, I have come to tell you that I wish to leave your house tomorrow and go to the ascetics.'", "در نیمه‌شب، سیدارتا به نزد پدرش رفت و پیش رویش ایستاد و گفت: «با اجازه‌ات، پدر، آمده‌ام بگویم که می‌خواهم فردا خانه‌ات را ترک کنم و به زاهدان بپیوندم.»"),
            StoryParagraph("The Brahmin was silent, and he was silent so long that the stars moved past the window and changed their pattern before the silence was broken.", "برهمن ساکت بود و آنقدر ساکت بود که ستارگان از پنجره گذشتند و الگویشان را تغییر دادند پیش از آنکه سکوت شکسته شود."),
            StoryParagraph("'It is not proper for a Brahmin to speak angry and violent words,' the father said at last. 'But my heart is angry and violent. I do not wish to hear this request a second time from your lips.'", "پدر سرانجام گفت: «شایسته برهمنی نیست که کلمات خشمگین و خشن بگوید. اما قلبم خشمگین و خشن است. نمی‌خواهم این درخواست را بار دومی از لبانت بشنوم.»"),
            StoryParagraph("Siddhartha stood silently, with his arms crossed, and did not move, and the father understood that his son was determined.", "سیدارتا بی‌حرکت ایستاد، با دستان ضربدری، و تکان نخورد و پدر فهمید پسرش مصمم است."),
            StoryParagraph("'You will grow tired and fall asleep on your feet before the sun rises,' the father said, and he went to bed, and Siddhartha stood there all night.", "پدر گفت: «خسته می‌شوی و پیش از طلوع خورشید روی پاهایت به خواب می‌روی.» و به رختخواب رفت و سیدارتا تمام شب آنجا ایستاد."),
            StoryParagraph("And when the morning came, and the father saw that his son was still standing, still silent, still determined, he said, 'Why do you wait?'", "و وقتی صبح آمد و پدر دید پسرش هنوز ایستاده، هنوز ساکت، هنوز مصمم، گفت: «چرا منتظری؟»"),
            StoryParagraph("'You know why,' said Siddhartha.", "سیدارتا گفت: «می‌دانی چرا.»"),
            StoryParagraph("'Will you stand there forever until daylight comes and I permit you?'", "«آیا تا ابد آنجا می‌ایستی تا سپیده بیاید و من اجازه دهم؟»"),
            StoryParagraph("'I will stand here,' said Siddhartha.", "سیدارتا گفت: «اینجا می‌ایستم.»"),
            StoryParagraph("'You will grow tired, Siddhartha.'", "«خسته می‌شوی، سیدارتا.»"),
            StoryParagraph("'I will grow tired.'", "«خسته می‌شوم.»"),
            StoryParagraph("'You will fall asleep, Siddhartha.'", "«به خواب می‌روی، سیدارتا.»"),
            StoryParagraph("'I will not fall asleep.'", "«به خواب نمی‌روم.»"),
            StoryParagraph("'You will die, Siddhartha.'", "«می‌میری، سیدارتا.»"),
            StoryParagraph("'I will die.'", "«می‌میرم.»"),
            StoryParagraph("The father rose from his bed, and he looked at his son, and he saw that his son had already left him, that his son was already standing somewhere else, in a world that was no longer the father's world.", "پدر از رختخوابش بلند شد و به پسرش نگاه کرد و دید پسرش از قبل ترکش کرده، پسرش از قبل جای دیگری ایستاده، در جهانی که دیگر جهان پدر نبود."),
            StoryParagraph("'Then go,' the father said, and his voice was quiet, and his voice was sad, and his voice was full of love. 'Go and find your way.'", "پدر گفت: «پس برو.» و صدایش آرام بود و صدایش اندوهناک بود و صدایش پر از عشق بود. «برو و راهت را پیدا کن.»"),
            StoryParagraph("And Siddhartha bowed to his father, and Siddhartha thanked him, and Siddhartha left the house, and Siddhartha began his journey.", "و سیدارتا به پدرش تعظیم کرد و سیدارتا از او تشکر کرد و سیدارتا خانه را ترک کرد و سیدارتا سفرش را آغاز کرد."),
            StoryParagraph("In the gray light of dawn, he walked through the empty streets of the town, past the temples, past the river, past the sleeping houses.", "در نور خاکستری سپیده، در خیابان‌های خالی شهر قدم زد، از کنار معابد، از کنار رودخانه، از کنار خانه‌های خواب."),
            StoryParagraph("And Govinda, who had been waiting for him at the edge of town, rose from his place, and joined him, and together they walked away.", "و گویندا، که در حاشیه شهر منتظرش بود، از جایش بلند شد و به او پیوست و با هم دور شدند.")
        )
    )

    // ─────────── فصل ۲: ساماناها ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Samanas", titlePersian = "ساماناها",
        paragraphs = listOf(
            StoryParagraph("In the evening of that day, they caught up with the Samanas, the skinny ascetics, and they offered them their company and their obedience.", "در عصر آن روز، به ساماناها رسیدند، زاهدان لاغراندام و شرکت و فرمانبرداری‌شان را به آنان پیشنهاد کردند."),
            StoryParagraph("They were accepted, and Siddhartha gave away his clothes to a poor Brahmin in exchange for the thin, unstitched garment of a Samana.", "پذیرفته شدند و سیدارتا لباسش را به برهمنی فقیر داد در ازای جامه نازک و بی‌دوخت سامانا."),
            StoryParagraph("He gave away his silk, and he gave away his sandals, and he kept only a cloth around his waist, and a cloak of hemp, and he was as the Samanas were.", "ابریشمش را داد و صندل‌هایش را داد و تنها پارچه‌ای دور کمرش و شنلی از کنف نگه داشت و همچون ساماناها بود."),
            StoryParagraph("He ate only once a day, and only what was offered to him, and never from a bowl, and never from a dish.", "روزی یک بار غذا می‌خورد، تنها آنچه به او تعارف می‌شد، هرگز از کاسه، هرگز از بشقاب."),
            StoryParagraph("He fasted for days, for weeks, for months; his flesh wasted away, and his eyes grew hollow in their sockets.", "روزها روزه گرفت، هفته‌ها، ماه‌ها؛ گوشتش تباه شد و چشمانش در حدقه‌هایشان گود افتادند."),
            StoryParagraph("He learned to reduce his breathing, to breathe with the smallest possible amount of air, to hold his breath for long periods.", "آموخت نفسش را کم کند، با کمترین هوای ممکن نفس بکشد، نفسش را برای مدت‌های طولانی نگه دارد."),
            StoryParagraph("He learned to concentrate his mind on a single thought, to empty it of all other thoughts, to become the thought itself.", "آموخت ذهنش را بر یک فکر متمرکز کند، از تمام افکار دیگر خالی‌اش کند، خودش فکر شود."),
            StoryParagraph("He learned to dwell in the void, to become nothing, to be as a stone, as a river, as a flame.", "آموخت در پوچی سکنی گزید، هیچ شد، همچون سنگی بود، همچون رودی، همچون شعل‌ای."),
            StoryParagraph("But though he could do all these things, he did not attain peace; he did not attain enlightenment; he did not attain liberation from suffering.", "اما با آنکه می‌توانست همه اینها را بکند، آرامش نیافت؛ روشن‌ضمیری نیافت؛ رهایی از رنج نیافت."),
            StoryParagraph("The oldest of the Samanas, a man of forty years of asceticism, taught him their ways, and Siddhartha learned them all.", "پیرترین سامانا، مردی با چهل سال زهد، راه‌هایشان را به او آموخت و سیدارتا همه را یاد گرفت."),
            StoryParagraph("But still he was not satisfied; the thirst in him was not quenched; the fire in him was not extinguished.", "اما هنوز راضی نبود؛ تشنگی درونش فروننشسته بود؛ آتش درونش خاموش نشده بود."),
            StoryParagraph("'What are we doing, Govinda?' he asked one day. 'Are we on the right path? Are we not walking in a circle?'", "یک روز پرسید: «چه می‌کنیم، گویندا؟ آیا در راه درستیم؟ آیا در دایره راه نمی‌رویم؟»"),
            StoryParagraph("'We are learning,' said Govinda, 'and we will continue to learn. We are becoming patient, we are becoming humble, we are becoming wise.'", "گویندا گفت: «می‌آموزیم و به آموختن ادامه می‌دهیم. صبور می‌شویم، فروتن می‌شویم، فرزانه می‌شویم.»"),
            StoryParagraph("'But what is the goal?' said Siddhartha. 'What is the end? The Samanas have been practicing for forty years, and they have not attained enlightenment.'", "سیدارتا گفت: «اما هدف چیست؟ پایان چیست؟ ساماناها چهل سال تمرین کرده‌اند و به روشن‌ضمیری نرسیده‌اند.»"),
            StoryParagraph("'The Buddha has attained enlightenment,' said Govinda. 'He was a prince, and he left his palace, and he sat under a tree, and he became the Enlightened One.'", "گویندا گفت: «بودا به روشن‌ضمیری رسیده. او شاهزاده‌ای بود و کاخش را رها کرد و زیر درختی نشست و روشن‌ضمیر شد.»"),
            StoryParagraph("'The Buddha,' said Siddhartha, and there was a strange light in his eyes. 'The Buddha has found the way. Let us go and hear him.'", "سیدارتا گفت: «بودا.» و نوری عجیب در چشمانش بود. «بودا راه را یافته. بیا برویم و بشنویمش.»"),
            StoryParagraph("The Samanas tried to persuade them to stay, but the two friends were determined; they had heard the call of the Buddha, and they could not ignore it.", "ساماناها تلاش کردند راضی‌شان کنند بمانند، اما دو دوست مصمم بودند؛ ندای بودا را شنیده بودند و نمی‌توانستند نادیده بگیرند."),
            StoryParagraph("So they left the Samanas, and they journeyed south, toward the place where the Buddha was said to be staying, in the grove of Jetavana.", "پس ساماناها را ترک کردند و به سمت جنوب سفر کردند، به سمت جایی که می‌گفتند بودا در آن اقامت دارد، در بیشه جتوانا."),
            StoryParagraph("The journey was long, and they had little food, and they suffered from hunger and thirst, but they did not give up.", "سفر طولانی بود و غذای اندکی داشتند و از گرسنگی و تشنگی رنج کشیدند، اما تسلیم نشدند."),
            StoryParagraph("Finally, they arrived at the grove, and there they saw the followers of the Buddha, hundreds of monks, all dressed in yellow robes, walking with slow and peaceful steps.", "سرانجام به بیشه رسیدند و آنجا پیروان بودا را دیدند، صدها راهب، همه در جامه‌های زرد، با قدم‌های آهسته و آرام راه می‌رفتند."),
            StoryParagraph("And in the middle of the grove, sitting beneath a tree, they saw the Buddha himself.", "و در میانه بیشه، زیر درختی نشسته، خود بودا را دیدند."),
            StoryParagraph("He was not tall, and he was not short, and he was not old, and he was not young; he was simply the Enlightened One, and his face radiated a peace that Siddhartha had never seen before.", "بلند نبود و کوتاه نبود، پیر نبود و جوان نبود؛ او تنها روشن‌ضمیر بود و چهره‌اش آرامشی می‌تاباند که سیدارتا هرگز پیش از آن ندیده بود."),
            StoryParagraph("Siddhartha watched him, and he felt that he was looking at the man who had found the answer to all his questions, the man who had discovered the way out of suffering.", "سیدارتا تماشایش کرد و حس کرد به مردی نگاه می‌کند که پاسخ تمام پرسش‌هایش را یافته، مردی که راه خروج از رنج را کشف کرده."),
            StoryParagraph("The Buddha began to speak, and his voice was calm and full of gentleness, and he spoke of suffering, and the cause of suffering, and the end of suffering, and the way to the end of suffering.", "بودا شروع به صحبت کرد و صدایش آرام و پر از لطافت بود و از رنج گفت و از علت رنج و از پایان رنج و از راه رسیدن به پایان رنج."),
            StoryParagraph("He spoke of the Four Noble Truths, and he spoke of the Eightfold Path, and he spoke of the Middle Way, which avoids both self-indulgence and self-mortification.", "از چهار حقیقت شریف گفت و از راه هشتگانه و از راه میانه که از هر دو افراط و تفریط پرهیز می‌کند."),
            StoryParagraph("Siddhartha listened, and he understood, and he was moved; and yet, even as he listened, he felt that this teaching, though it was true, was not the whole truth.", "سیدارتا گوش داد و فهمید و متأثر شد؛ و با این حال، در همان حال که گوش می‌داد، حس کرد این تعالیم، هرچند درست، تمام حقیقت نبود."),
            StoryParagraph("For the Buddha taught the way to overcome suffering, but he did not teach what Siddhartha wanted to know: what is the self, what is the Atman, what is the nature of existence?", "زیرا بودا راه غلبه بر رنج را آموخت، اما آنچه سیدارتا می‌خواست بداند را نیاموخت: خود چیست، آتمان چیست، ماهیت وجود چیست؟"),
            StoryParagraph("Govinda, however, was completely won over; he decided to become a follower of the Buddha, to join the Sangha, the community of monks.", "اما گویندا کاملاً فتح شده بود؛ تصمیم گرفت پیرو بودا شود، به سانگا بپیوندد، جامعه راهبان."),
            StoryParagraph("Siddhartha did not; he respected the Buddha, he honored the Buddha, but he could not follow him; he had to find his own way.", "سیدارتا نکرد؛ بودا را محترم می‌داشت، احترام می‌گذاشت، اما نمی‌توانست پیروی‌اش کند؛ باید راه خودش را پیدا می‌کرد."),
            StoryParagraph("And so, one morning, he said goodbye to his friend Govinda, and he said goodbye to the Buddha, and he went on alone.", "و اینگونه، یک صبح، با دوستش گویندا خداحافظی کرد و با بودا خداحافظی کرد و تنها رفت."),
            StoryParagraph("And the Buddha, who understood, did not try to stop him; he simply blessed him, and watched him go with kindness in his eyes.", "و بودا، که می‌فهمید، تلاش نکرد متوقفش کند؛ تنها برکتش داد و با مهربانی در چشمانش تماشا کرد که می‌رود."),
            StoryParagraph("For the Buddha knew that each being must find their own way, that no one can walk another's path, that salvation is personal and cannot be given.", "زیرا بودا می‌دانست هر موجودی باید راه خودش را بیابد، هیچ‌کس نمی‌تواند راه دیگری را بپیماید، رستگاری شخصی است و نمی‌شود داد."),
            StoryParagraph("And so Siddhartha went on, alone, into the world, to find what he was seeking, to discover what he had always known but could not yet see.", "و اینگونه سیدارتا به راه افتاد، تنها، به میان جهان، تا آنچه می‌جست را بیابد، تا آنچه همیشه می‌دانست اما هنوز نمی‌توانست ببیند را کشف کند.")
        )
    )

    // ─────────── فصل ۳: کامالا ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Kamala", titlePersian = "کامالا",
        paragraphs = listOf(
            StoryParagraph("Siddhartha walked through the forest, and he walked through the fields, and he walked through the towns, and he came at last to a great city.", "سیدارتا در جنگل قدم زد و در مزارع و در شهرها و سرانجام به شهری بزرگ رسید."),
            StoryParagraph("It was a city of wealth and pleasure, a city of merchants and courtesans, a city where everything could be bought and sold.", "شهری بود از ثروت و لذت، شهری از تاجران و روسپیان، شهری که در آن هر چیزی می‌شد خرید و فروخت."),
            StoryParagraph("In this city lived Kamala, the most famous courtesan in the land, the most beautiful woman in the region.", "در این شهر کامالا زندگی می‌کرد، مشهورترین روسپی سرزمین، زیباترین زن منطقه."),
            StoryParagraph("She was not merely beautiful, however; she was also intelligent, sophisticated, and wise in the ways of the world.", "اما تنها زیبا نبود؛ باهوش هم بود، مجرب، و فرزانه در راه‌های دنیا."),
            StoryParagraph("Siddhartha saw her, one day, as she was being carried in her palanquin through the streets, and he was struck by her beauty.", "سیدارتا یک روز او را دید که در کجاوه‌اش در خیابان‌ها حمل می‌شد و زیبایی‌اش تحت تأثیرش قرار داد."),
            StoryParagraph("He decided that he wanted to learn from her, that he wanted to know what she knew, that he wanted to experience what she could teach.", "تصمیم گرفت می‌خواهد از او بیاموزد، می‌خواهد آنچه می‌داند را بداند، می‌خواهد آنچه می‌تواند بیاموزد را تجربه کند."),
            StoryParagraph("He went to her house, and he asked to see her, and he was admitted into her presence.", "به خانه‌اش رفت و خواست ببیندش و به حضور او راه یافت."),
            StoryParagraph("'I am Siddhartha, a Samana, a wanderer,' he said. 'I have come to learn from you.'", "گفت: «من سیدارتم، سامانایی، سرگردانی. آمده‌ام از تو بیاموزم.»"),
            StoryParagraph("'From me?' she said, and she laughed, and her laugh was like music. 'What could a Samana learn from a courtesan?'", "گفت: «از من؟» و خندید و خنده‌اش مثل موسیقی بود. «یک سامانا از یک روسپی چه می‌تواند بیاموزد؟»"),
            StoryParagraph("'To love,' said Siddhartha. 'To know the world. To know myself.'", "سیدارتا گفت: «عشق ورزیدن. شناختن دنیا. شناختن خودم.»"),
            StoryParagraph("Kamala looked at him for a long time, and there was something in his eyes that interested her, something she had not seen before in the eyes of the men who came to her.", "کامالا مدت طولانی نگاهش کرد و چیزی در چشمانش بود که علاقه‌مندش کرد، چیزی که در چشمان مردانی که به سراغش می‌آمدند ندیده بود."),
            StoryParagraph("'You are beautiful, Samana,' she said, 'and you are intelligent, and you know how to speak. But you are also poor; you have nothing to give me.'", "گفت: «زیبایی، سامانا، و باهوشی و می‌دانی چگونه صحبت کنی. اما فقیری هم؛ چیزی نداری که به من بدهی.»"),
            StoryParagraph("'I have nothing material,' said Siddhartha. 'But I have what I have learned: I can think, I can wait, I can fast.'", "سیدارتا گفت: «چیزی مادی ندارم. اما آنچه آموخته‌ام را دارم: می‌توانم فکر کنم، می‌توانم صبر کنم، می‌توانم روزه بگیرم.»"),
            StoryParagraph("'What use are these to me?' said Kamala, and again she laughed, but there was also a glint of curiosity in her eyes.", "گفت: «این‌ها به چه کارم می‌آیند؟» و دوباره خندید، اما برق کنجکاوی هم در چشمانش بود."),
            StoryParagraph("'They are of no use to you,' Siddhartha admitted. 'But they are of use to me. And perhaps, one day, they will be of use to you.'", "سیدارتا پذیرفت: «به کار تو نمی‌آیند. اما به کار من می‌آیند. و شاید، روزی، به کار تو هم بیایند.»"),
            StoryParagraph("Kamala was intrigued; she had never met anyone like this before; she had never met anyone who wanted nothing from her but knowledge.", "کامالا مجذوب شد؛ هرگز کسی مثل او ندیده بود؛ هرگز کسی ندیده بود که از او چیزی نخواهد جز دانش."),
            StoryParagraph("'Very well,' she said. 'I will teach you, if you will do one thing for me: you must come to me dressed in fine clothes, with shoes on your feet, and with money in your purse.'", "گفت: «بسیار خوب. به تو می‌آموزم، اگر یک کار برایم بکنی: باید با لباس‌های فاخر به دیدنم بیایی، با کفش در پایت و پول در کیسه‌ات.»"),
            StoryParagraph("'Why?' asked Siddhartha.", "سیدارتا پرسید: «چرا؟»"),
            StoryParagraph("'Because I am a courtesan,' said Kamala, 'and I cannot be seen with a beggar. Because appearance matters in this world, and if you want to learn from me, you must learn also to appear as one of us.'", "کامالا گفت: «چون من روسپی‌ام و نمی‌توانم با گدایی دیده شوم. چون ظاهر در این دنیا مهم است و اگر می‌خواهی از من بیاموزی، باید یاد بگیری همچون یکی از ما ظاهر شوی.»"),
            StoryParagraph("Siddhartha understood, and he agreed; and he went into the city, and he found work with a merchant named Kamaswami.", "سیدارتا فهمید و موافقت کرد؛ به شهر رفت و نزد تاجری به نام کاماسوامی کار یافت."),
            StoryParagraph("Kamaswami was a shrewd businessman, and he was skeptical of Siddhartha at first; but Siddhartha's intelligence and patience impressed him, and he hired the young man as his assistant.", "کاماسوامی تاجری زیرک بود و ابتدا به سیدارتا بدگمان بود؛ اما هوش و صبر سیدارتا او را تحت تأثیر قرار داد و جوان را به‌عنوان دستیارش استخدام کرد."),
            StoryParagraph("Siddhartha learned the ways of business quickly; he learned to buy and sell, to negotiate and to bargain, to manage money and to manage men.", "سیدارتا به‌سرعت راه‌های تجارت را یاد گرفت؛ آموخت بخرد و بفروشد، مذاکره و چانه‌زنی کند، پول و مردان را مدیریت کند."),
            StoryParagraph("But he did not care about the money; he did not care about the profit; he cared only about learning, about experiencing, about understanding.", "اما به پول اهمیت نمی‌داد؛ به سود اهمیت نمی‌داد؛ تنها به یادگیری اهمیت می‌داد، به تجربه کردن، به فهمیدن."),
            StoryParagraph("And so, gradually, he became rich; he bought fine clothes, and shoes, and a house; and he went to Kamala, and she accepted him as her student.", "و اینگونه، آرام‌آرام، ثروتمند شد؛ لباس‌های فاخر خرید، کفش، خانه‌ای؛ و به نزد کامالا رفت و او او را به‌عنوان شاگردش پذیرفت."),
            StoryParagraph("Kamala taught him the art of love, which she said was not different from the art of life; it required attention, patience, and the willingness to give without expectation of return.", "کامالا هنر عشق را به او آموخت که به گفته‌اش متفاوت از هنر زندگی نبود؛ توجه می‌خواست، صبر، و آمادگی بخشیدن بدون انتظار بازگشت."),
            StoryParagraph("She taught him how to dress, how to speak, how to behave in society; she taught him how to be a man of the world.", "به او آموخت چگونه لباس بپوشد، چگونه صحبت کند، چگونه در جامعه رفتار کند؛ آموخت چگونه مرد دنیا باشد."),
            StoryParagraph("She taught him how to love a woman, how to please her, how to give her pleasure; and she taught him how to receive love as well, how to accept it without guilt or shame.", "به او آموخت چگونه زنی را دوست بدارد، چگونه راضی‌اش کند، چگونه لذتش دهد؛ و آموخت چگونه عشق را هم دریافت کند، چگونه بدون گناه یا شرم بپذیردش."),
            StoryParagraph("For years, Siddhartha lived in the city, and for years, he learned from Kamala; and slowly, imperceptibly, he began to forget what he had come to seek.", "سال‌ها سیدارتا در شهر زندگی کرد و سال‌ها از کامالا آموخت؛ و آرام‌آرام، نامحسوس، شروع کرد به فراموش کردن آنچه آمده بود بجوید."),
            StoryParagraph("He began to care about money, about possessions, about status; he began to enjoy the pleasures of the flesh, the taste of wine, the thrill of gambling.", "شروع کرد به اهمیت دادن به پول، به دارایی، به مقام؛ شروع کرد به لذت بردن از لذت‌های جسم، طعم شراب، هیجان قمار."),
            StoryParagraph("He became greedy, he became selfish, he became cruel; the Samana within him died, and the merchant within him was born.", "حریص شد، خودخواه شد، بی‌رحم شد؛ سامانای درونش مرد و تاجر درونش زاده شد."),
            StoryParagraph("One night, he had a dream, a terrible dream, in which he saw Kamala's songbird die in its cage; and he woke up, and he knew that something had gone wrong.", "یک شب کابوسی دید، کابوسی وحشتناک، که در آن پرنده آوازخوان کامالا در قفسش مرده بود؛ و بیدار شد و دانست چیزی اشتباه شده."),
            StoryParagraph("He looked at himself in the mirror, and he saw a face that he did not recognize, a face that was old and tired and full of desire.", "خودش را در آینه نگاه کرد و چهره‌ای دید که نمی‌شناخت، چهره‌ای پیر و خسته و پر از میل."),
            StoryParagraph("He realized that he had lost his way, that he had become everything he had once despised, that he had forgotten the purpose of his journey.", "فهمید راهش را گم کرده، به هر چیزی تبدیل شده که زمانی تحقیر می‌کرد، هدف سفرش را فراموش کرده."),
            StoryParagraph("And so, one night, without saying goodbye to anyone, he left the city, he left Kamala, he left everything he had accumulated.", "و اینگونه، یک شب، بدون خداحافظی با کسی، شهر را ترک کرد، کامالا را ترک کرد، هر چیزی که انباشته بود را ترک کرد."),
            StoryParagraph("He walked into the forest, and he walked for many days, and he walked until he came to a great river, the same river he had crossed years before.", "به جنگل رفت و روزهای بسیاری راه رفت و تا رسیدن به رودی بزرگ راه رفت، همان رودی که سال‌ها پیش از آن گذشته بود."),
            StoryParagraph("He stood on the bank of the river, and he felt a great weariness, a great despair, a great longing for death.", "در ساحل رود ایستاد و خستگی بزرگی حس کرد، ناامیدی بزرگی، اشتیاق بزرگی به مرگ."),
            StoryParagraph("He thought about ending his life in the river, about sinking into the water and never coming up again.", "به پایان دادن زندگی‌اش در رود فکر کرد، به فرو رفتن در آب و هرگز بالا نیامدن."),
            StoryParagraph("But as he stood there, as he prepared to let himself fall, a word came to him, a word from his childhood, a word from the ancient teachings: the word Om.", "اما همانطور که آنجا ایستاده بود، همانطور که آماده می‌شد خودش را بیندازد، کلمه‌ای به ذهنش آمد، کلمه‌ای از کودکی‌اش، کلمه‌ای از تعالیم کهن: کلمه اوم."),
            StoryParagraph("And with that word, something in him awakened, something that had been sleeping for years, something that had never quite died.", "و با آن کلمه، چیزی در او بیدار شد، چیزی که سال‌ها خوابیده بود، چیزی که هرگز کاملاً نمرده بود."),
            StoryParagraph("He did not jump; he did not die; he simply sat down by the river, and he wept, and then he slept, and when he woke, he was a different man.", "نپرید؛ نمرد؛ تنها کنار رود نشست و گریست و بعد خوابید و وقتی بیدار شد، مردی دیگر بود.")
        )
    )

    // ─────────── فصل ۴: وازودوا ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Vasudeva", titlePersian = "وازودوا",
        paragraphs = listOf(
            StoryParagraph("Siddhartha woke up by the river, and he felt as if he had been asleep for a very long time, as if he had been reborn.", "سیدارتا کنار رود بیدار شد و حس کرد گویی مدت‌های بسیار طولانی خواب بوده، گویی دوباره زاده شده."),
            StoryParagraph("He sat up, and he looked at the river, and he saw that the river was beautiful, more beautiful than he had ever noticed before.", "نشست و به رود نگاه کرد و دید رود زیباست، زیباتر از آنچه هرگز قبلاً متوجه شده بود."),
            StoryParagraph("He saw the water flowing, endlessly flowing, never the same water, always the same river.", "دید آب جاری است، بی‌پایان جاری، هرگز همان آب، همیشه همان رود."),
            StoryParagraph("And as he sat there, a man came along the path, an old ferryman, with a kind face and calm eyes.", "و همانطور که آنجا نشسته بود، مردی در راه آمد، قایق‌ران پیری، با چهره‌ای مهربان و چشمانی آرام."),
            StoryParagraph("'You look tired, stranger,' the ferryman said. 'Rest here. The river will take care of you.'", "قایق‌ران گفت: «خسته به نظر می‌رسی، غریبه. اینجا استراحت کن. رود از تو مراقبت می‌کند.»"),
            StoryParagraph("'The river?' said Siddhartha. 'The river takes care of you?'", "سیدارتا گفت: «رود؟ رود از تو مراقبت می‌کند؟»"),
            StoryParagraph("'Yes,' said the ferryman. 'The river taught me everything I know. The river is my teacher, my friend, my god.'", "قایق‌ران گفت: «بله. رود هر چیزی که می‌دانم به من آموخت. رود معلمم است، دوستم، خدایم.»"),
            StoryParagraph("'What is your name?' asked Siddhartha.", "سیدارتا پرسید: «نامت چیست؟»"),
            StoryParagraph("'Vasudeva,' said the ferryman. 'And I have been waiting for you.'", "قایق‌ران گفت: «وازودوا. و منتظرت بوده‌ام.»"),
            StoryParagraph("'How did you know I would come?' asked Siddhartha.", "سیدارتا پرسید: «چگونه دانستی می‌آیم؟»"),
            StoryParagraph("'The river told me,' said Vasudeva. 'The river tells me everything. It told me that you would come, and that you would stay.'", "وازودوا گفت: «رود به من گفت. رود همه چیز را به من می‌گوید. گفت که می‌آیی و می‌مانی.»"),
            StoryParagraph("Siddhartha did not understand, but he felt a strange peace in the presence of the old ferryman; he felt that he had come home.", "سیدارتا نفهمید، اما در حضور قایق‌ران پیر آرامشی عجیب حس کرد؛ حس کرد به خانه رسیده."),
            StoryParagraph("'I will stay,' said Siddhartha, 'if you will teach me.'", "سیدارتا گفت: «می‌مانم، اگر به من بیاموزی.»"),
            StoryParagraph("'I will not teach you,' said Vasudeva. 'The river will teach you. I will simply be here, to remind you of what you already know.'", "وازودوا گفت: «من نمی‌آموزم. رود به تو می‌آموزد. من تنها اینجا خواهم بود، تا یادت آورم آنچه از قبل می‌دانی.»"),
            StoryParagraph("And so Siddhartha stayed with Vasudeva, and he became his apprentice, and he learned to be a ferryman.", "و اینگونه سیدارتا با وازودوا ماند و شاگردش شد و آموخت قایق‌ران باشد."),
            StoryParagraph("He learned to build boats, and to repair them, and to row them across the river; he learned to fish, and to cook, and to live simply.", "آموخت قایق بسازد، تعمیرشان کند، آن‌ها را از رود بگذراند؛ آموخت ماهی بگیرد، آشپزی کند، ساده زندگی کند."),
            StoryParagraph("But most of all, he learned to listen to the river; he learned to hear the voices in the water, the laughter and the tears, the joy and the sorrow.", "اما بیش از همه، آموخت به رود گوش دهد؛ آموخت صداهای درون آب را بشنود، خنده و اشک، شادی و اندوه."),
            StoryParagraph("The river, he discovered, contained all the voices of the world: the voices of gods and men, of animals and plants, of the living and the dead.", "رود، کشف کرد، همه صداهای جهان را در خود داشت: صداهای خدایان و انسان‌ها، حیوانات و گیاهان، زندگان و مردگان."),
            StoryParagraph("And among all those voices, one voice was always present, the voice of the river itself, the voice of unity, the voice of Om.", "و در میان همه آن صداها، یک صدا همیشه حاضر بود، صدای خود رود، صدای وحدت، صدای اوم."),
            StoryParagraph("Years passed, and Siddhartha grew older, and his face became calm, and his eyes became peaceful; he had found what he had been seeking.", "سال‌ها گذشت و سیدارتا پیرتر شد و چهره‌اش آرام شد و چشمانش صلح‌جو شد؛ آنچه می‌جست را یافته بود."),
            StoryParagraph("But his peace would be tested; one day, Kamala appeared on the far bank of the river, with a young boy, and with a group of pilgrims.", "اما آرامشش آزموده می‌شد؛ یک روز، کامالا در ساحل دور رود ظاهر شد، با پسری جوان، با گروهی از زائران."),
            StoryParagraph("She was on her way to see the Buddha, who was said to be dying; she wanted to pay her respects, to see the Enlightened One before he passed.", "او در راه دیدن بودا بود، که می‌گفتند در حال مرگ است؛ می‌خواست احترامش را به جا آورد، روشن‌ضمیر را پیش از رفتنش ببیند."),
            StoryParagraph("But as she approached the river, she was bitten by a snake, and she collapsed, and she cried out for help.", "اما همانطور که به رود نزدیک می‌شد، ماری گزیدش و افتاد و فریاد کمک زد."),
            StoryParagraph("Siddhartha, who was on the bank, heard the cry, and he ran to her, and he lifted her up, and he carried her to the hut.", "سیدارتا که در ساحل بود فریاد را شنید و به سمتش دوید و بلندش کرد و به کلبه برد."),
            StoryParagraph("Kamala was dying, but she recognized Siddhartha, and she smiled, and she said, 'I have found you at last.'", "کامالا در حال مرگ بود اما سیدارتا را شناخت و لبخند زد و گفت: «سرانجام پیدایت کردم.»"),
            StoryParagraph("The boy with her, she said, was Siddhartha's son; he had been born after Siddhartha left the city, and he had been raised by Kamala alone.", "پسری که با او بود، گفت، پسر سیدارتا بود؛ بعد از رفتن سیدارتا از شهر زاده شده و کامالا تنهایی بزرگش کرده بود."),
            StoryParagraph("Kamala died that night, and Siddhartha was left with his son, a boy of eleven years, who had never known his father, who did not want a father.", "کامالا آن شب مرد و سیدارتا با پسرش ماند، پسری یازده ساله، که هرگز پدرش را نشناخته بود، که پدر نمی‌خواست."),
            StoryParagraph("The boy was spoiled and stubborn, and he did not want to live with Siddhartha, and he did not want to be a ferryman, and he did not want to learn the ways of the river.", "پسر لوس و لجباز بود و نمی‌خواست با سیدارتا زندگی کند، نمی‌خواست قایق‌ران باشد، نمی‌خواست راه‌های رود را بیاموزد."),
            StoryParagraph("He wanted to go back to the city, to the wealth and the pleasures that he had known; he wanted his mother, and she was dead; he wanted his old life, and it was gone.", "می‌خواست به شهر برگردد، به ثروت و لذت‌هایی که می‌شناخت؛ مادرش را می‌خواست و او مرده بود؛ زندگی قبلی‌اش را می‌خواست و رفته بود."),
            StoryParagraph("Siddhartha tried to teach him, tried to be patient, tried to love him; but the boy resisted, and Siddhartha suffered, and the suffering was greater than any he had known before.", "سیدارتا تلاش کرد بیاموزدش، تلاش کرد صبور باشد، تلاش کرد دوستش بدارد؛ اما پسر مقاومت کرد و سیدارتا رنج کشید و این رنج از هر آنچه قبلاً شناخته بود بزرگ‌تر بود."),
            StoryParagraph("And so, at last, Siddhartha had to let him go; he had to allow his son to leave, to return to the city, to live his own life, to make his own mistakes.", "و اینگونه، سرانجام، سیدارتا مجبور شد رهایش کند؛ مجبور شد بگذارد پسرش برود، به شهر برگردد، زندگی خودش را بکند، اشتباهات خودش را بکند."),
            StoryParagraph("This was the hardest lesson of all, the lesson that he could not control another's life, that he could not protect another from suffering, that each being must find their own way.", "این سخت‌ترین درس از همه بود، درسی که نمی‌توانست زندگی دیگری را کنترل کند، نمی‌توانست دیگری را از رنج محافظت کند، هر موجودی باید راه خودش را بیابد."),
            StoryParagraph("And Vasudeva, the old ferryman, helped him; he listened, and he did not judge, and he did not give advice; he simply was there, in silence, in presence, in understanding.", "و وازودوا، قایق‌ران پیر، کمکش کرد؛ گوش داد و قضاوت نکرد و نصیحت نکرد؛ تنها آنجا بود، در سکوت، در حضور، در فهم."),
            StoryParagraph("'Listen to the river,' Vasudeva said. 'The river knows. The river always knows. Listen to the river, and you will find peace.'", "وازودوا گفت: «به رود گوش بده. رود می‌داند. رود همیشه می‌داند. به رود گوش بده و آرامش می‌یابی.»"),
            StoryParagraph("Siddhartha listened, and he heard the river, and he heard all the voices in the river, and he heard the voice of Om, and he found peace.", "سیدارتا گوش داد و رود را شنید و همه صداهای درون رود را شنید و صدای اوم را شنید و آرامش یافت."),
            StoryParagraph("The river had taught him the final lesson: that all things are one, that all voices are one voice, that all beings are the same being.", "رود درس نهایی را به او آموخته بود: همه چیز یکی است، همه صداها یک صداست، همه موجودات همان یک موجودند."),
            StoryParagraph("And Vasudeva, who had taught him this, who had been his teacher, who had been his friend, said goodbye one day and walked into the forest.", "و وازودوا، که این را به او آموخته بود، که معلمش بوده، که دوستش بوده، یک روز خداحافظی کرد و در جنگل ناپدید شد."),
            StoryParagraph("He had completed his task; he had led Siddhartha to enlightenment; and now, like the Buddha before him, he left quietly, without fuss, without ceremony.", "وظیفه‌اش را کامل کرده بود؛ سیدارتا را به روشن‌ضمیری رسانده بود؛ و حالا، همچون بودای پیش از خودش، بی‌صدا رفت، بی‌هیاهو، بی‌مراسم."),
            StoryParagraph("Siddhartha was alone at the river now, alone with the river, alone with the voices, alone with the peace that he had sought for so many years.", "سیدارتا حالا کنار رود تنها بود، تنها با رود، تنها با صداها، تنها با آرامشی که این همه سال در جستجویش بود."),
            StoryParagraph("He continued to be a ferryman; he continued to ferry travelers across the river; he continued to listen to the river, and to learn from it, and to teach those who were willing to listen.", "به قایق‌رانی ادامه داد؛ به گذراندن مسافران از رود ادامه داد؛ به گوش دادن به رود، به آموختن از آن، به آموزش دادن به کسانی که مایل به گوش دادن بودند ادامه داد."),
            StoryParagraph("But he taught not with words, but with presence; not with doctrine, but with being; not with argument, but with the simple, silent example of his life.", "اما نه با کلمات آموخت، بلکه با حضور؛ نه با عقیده، بلکه با بودن؛ نه با استدلال، بلکه با مثال ساده و ساکت زندگی‌اش."),
            StoryParagraph("And those who came to him, those who crossed on his ferry, those who sat with him by the river, learned something that no book could teach, that no teacher could give.", "و کسانی که به نزدش می‌آمدند، کسانی که با قایقش می‌گذشتند، کسانی که کنارش در رود می‌نشستند، چیزی می‌آموختند که هیچ کتابی نمی‌توانست بیاموزد، هیچ معلمی نمی‌توانست بدهد."),
            StoryParagraph("For they learned that wisdom is not a thing to be possessed, but a way of being; not a knowledge to be accumulated, but a life to be lived.", "زیرا می‌آموختند که خرد چیزی نیست که مالک شود، بلکه شیوه‌ای از بودن است؛ دانشی نیست که انباشته شود، بلکه زندگی‌ای است که باید زیسته شود."),
            StoryParagraph("And Siddhartha, the Brahmin's son, the Samana, the merchant, the ferryman, had become, at last, what he had always been: a man at peace with himself and with the world.", "و سیدارتا، پسر برهمن، سامانا، تاجر، قایق‌ران، سرانجام به آنچه همیشه بوده تبدیل شده بود: مردی در صلح با خود و با جهان.")
        )
    )

    // ─────────── فصل ۵: گویندا ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Govinda", titlePersian = "گویندا",
        paragraphs = listOf(
            StoryParagraph("Many years had passed, and Govinda, the friend of Siddhartha's youth, had become an old monk, respected for his wisdom and his piety.", "سال‌های بسیاری گذشته بود و گویندا، دوست جوانی سیدارتا، راهبی پیر شده بود، محترم برای خرد و تقوایش."),
            StoryParagraph("He had followed the Buddha all his life, and he had learned the teachings by heart, and he had practiced them faithfully, and he had taught them to others.", "تمام عمرش پیرو بودا بود و تعالیم را از حفظ آموخته بود و با وفاداری تمرینشان کرده بود و به دیگران آموخته بود."),
            StoryParagraph("But he had not attained enlightenment; he had not found the peace that the Buddha had promised; he had not discovered the truth that he had been seeking for so many years.", "اما به روشن‌ضمیری نرسیده بود؛ آرامشی که بودا وعده داده بود را نیافته بود؛ حقیقتی که این همه سال در جستجویش بود را کشف نکرده بود."),
            StoryParagraph("One day, he heard a rumor that there was an old ferryman on the river who was said to be a sage, who was said to have found what others had not.", "یک روز، شایعه‌ای شنید که بر رود قایق‌ران پیری بود که می‌گفتند فرزانه است، می‌گفتند آنچه دیگران نیافته‌اند را یافته."),
            StoryParagraph("Govinda decided to visit him, to see for himself, to ask the questions that had been troubling him for so long.", "گویندا تصمیم گرفت ملاقاتش کند، خودش ببیند، پرسش‌هایی را که این همه مدت ناراحتش کرده بودند بپرسد."),
            StoryParagraph("He traveled to the river, and he found the ferryman, and he was struck by the peace in the old man's face, a peace that he had seen only once before, in the face of the Buddha.", "به رود سفر کرد و قایق‌ران را یافت و از آرامش در چهره پیرمرد متأثر شد، آرامشی که تنها یک بار پیش از این دیده بود، در چهره بودا."),
            StoryParagraph("'Are you Siddhartha?' asked Govinda, and his voice trembled, for he had recognized his old friend.", "گویندا پرسید: «تو سیدارتایی؟» و صدایش لرزید، زیرا دوست قدیمی‌اش را شناخته بود."),
            StoryParagraph("'I am Siddhartha,' said the ferryman, and he smiled, and his smile was warm and welcoming and utterly without guile.", "قایق‌ران گفت: «من سیدارتم.» و لبخند زد و لبخندش گرم و خوش‌آمدگو و کاملاً بدون حیله بود."),
            StoryParagraph("'I have been looking for you,' said Govinda. 'I have been looking for you all my life, and I did not know it.'", "گویندا گفت: «در جستجوی تو بوده‌ام. تمام عمرم در جستجوی تو بوده‌ام و نمی‌دانستم.»"),
            StoryParagraph("'And now you have found me,' said Siddhartha. 'Sit, my friend, and let us talk.'", "سیدارتا گفت: «و حالا یافته‌ای. بنشین، دوستم، و صحبت کنیم.»"),
            StoryParagraph("They sat together by the river, the two old men, the two friends, the two seekers, and they talked about the years that had passed.", "کنار رود نشستند، دو پیرمرد، دو دوست، دو جوینده و از سال‌هایی که گذشته بود صحبت کردند."),
            StoryParagraph("Siddhartha told Govinda about his journey, about Kamala, about his son, about the river, about everything that had happened to him.", "سیدارتا برای گویندا از سفرش گفت، از کامالا، از پسرش، از رود، از هر چیزی که برایش اتفاق افتاده بود."),
            StoryParagraph("And Govinda told Siddhartha about his life as a monk, about his faithfulness to the Buddha, about his struggles and his doubts.", "و گویندا برای سیدارتا از زندگی راهبی‌اش گفت، از وفاداری‌اش به بودا، از کشمکش‌ها و شک‌هایش."),
            StoryParagraph("'I have followed the Buddha for fifty years,' said Govinda, 'and I have not found what he promised. I have not found enlightenment.'", "گویندا گفت: «پنجاه سال پیرو بودا بوده‌ام و آنچه وعده داده بود را نیافته‌ام. روشن‌ضمیری را نیافته‌ام.»"),
            StoryParagraph("'What is enlightenment?' asked Siddhartha. 'Is it a thing that can be found? Is it a thing that can be given?'", "سیدارتا پرسید: «روشن‌ضمیری چیست؟ چیزی است که یافت شود؟ چیزی است که داده شود؟»"),
            StoryParagraph("'I do not know,' said Govinda. 'I only know that I have not found it, and that I am tired of seeking.'", "گویندا گفت: «نمی‌دانم. تنها می‌دانم که نیافته‌ام و از جستجو خسته‌ام.»"),
            StoryParagraph("'Perhaps,' said Siddhartha, 'that is the beginning. Perhaps you must stop seeking before you can find.'", "سیدارتا گفت: «شاید این آغاز است. شاید باید جستجو را رها کنی تا بتوانی بیابی.»"),
            StoryParagraph("'What do you mean?' asked Govinda.", "گویندا پرسید: «منظورت چیست؟»"),
            StoryParagraph("'When you seek,' said Siddhartha, 'you see only what you are seeking; you do not see what is there. But when you stop seeking, when you become still, when you become open, then you see everything, and everything is truth.'", "سیدارتا گفت: «وقتی می‌جویی، تنها آنچه را می‌جویی می‌بینی؛ آنچه آنجاست را نمی‌بینی. اما وقتی جستجو را رها می‌کنی، وقتی ساکن می‌شوی، وقتی باز می‌شوی، آن وقت همه چیز را می‌بینی و همه چیز حقیقت است.»"),
            StoryParagraph("Govinda did not fully understand, but he felt that there was wisdom in his friend's words, a wisdom that he had not encountered in all his years of study.", "گویندا کاملاً نفهمید، اما حس کرد در کلمات دوستش خردی هست، خردی که در تمام سال‌های مطالعه‌اش با آن روبرو نشده بود."),
            StoryParagraph("'Let me tell you something,' said Siddhartha. 'I have had many teachers in my life, and I have learned from each of them. But the greatest teacher of all was the river.'", "سیدارتا گفت: «بگذار چیزی به تو بگویم. در زندگی‌ام معلمان بسیاری داشته‌ام و از هر یک آموخته‌ام. اما بزرگ‌ترین معلم از همه رود بود.»"),
            StoryParagraph("'The river?' said Govinda, surprised.", "گویندا حیرت‌زده گفت: «رود؟»"),
            StoryParagraph("'Yes,' said Siddhartha. 'The river has taught me that all things are one, that everything flows, that nothing is permanent, and yet nothing is lost.'", "سیدارتا گفت: «بله. رود به من آموخته که همه چیز یکی است، همه چیز جاری است، هیچ چیز پایدار نیست و با این حال هیچ چیز از دست نمی‌رود.»"),
            StoryParagraph("'The river has taught me that the past and the future are illusions, that only the present exists, and that the present is everything.'", "«رود به من آموخته گذشته و آینده توهم‌اند، تنها حال وجود دارد و حال همه چیز است.»"),
            StoryParagraph("'The river has taught me that wisdom cannot be taught, that knowledge can be communicated but wisdom cannot, that each being must find their own way.'", "«رود به من آموخته خرد را نمی‌توان آموخت، دانش را می‌توان منتقل کرد اما خرد را نه، هر موجودی باید راه خودش را بیابد.»"),
            StoryParagraph("'The river has taught me that love is the most important thing in the world, that love is what binds all beings together, that love is the truth of existence.'", "«رود به من آموخته عشق مهم‌ترین چیز در جهان است، عشق آن چیزی است که همه موجودات را به هم پیوند می‌دهد، عشق حقیقت وجود است.»"),
            StoryParagraph("Govinda listened, and he was moved, and he felt that his friend had found something that he himself had not found, a peace that he himself did not possess.", "گویندا گوش داد و متأثر شد و حس کرد دوستش چیزی یافته که خودش نیافته، آرامشی که خودش ندارد."),
            StoryParagraph("'I do not understand everything you say,' said Govinda, 'but I feel that there is truth in it, and I am grateful that you have shared it with me.'", "گویندا گفت: «همه آنچه می‌گویی نمی‌فهمم، اما حس می‌کنم حقیقتی در آن هست و سپاسگزارم که با من قسمت کردی.»"),
            StoryParagraph("'Would you like to kiss me?' asked Siddhartha. 'I have heard that when a man kisses a sage, he receives a portion of the sage's wisdom.'", "سیدارتا پرسید: «می‌خواهی مرا ببوسی؟ شنیده‌ام وقتی کسی فرزان‌های را می‌بوسد، بخشی از خرد او را دریافت می‌کند.»"),
            StoryParagraph("Govinda hesitated, then leaned forward, then kissed his friend on the forehead; and in that moment, he experienced something that he had never experienced before.", "گویندا تردید کرد، بعد به جلو خم شد، بعد دوستش را بر پیشانی بوسید؛ و در آن لحظه چیزی را تجربه کرد که هرگز قبلاً تجربه نکرده بود."),
            StoryParagraph("He saw all things, and all beings, and all times; he saw the world as it truly was, in all its beauty and all its terror; and he felt a peace that he had never felt before.", "همه چیز را دید و همه موجودات و همه زمان‌ها؛ جهان را آن‌گونه که واقعاً بود دید، در تمام زیبایی و تمام وحشتش؛ و آرامشی حس کرد که هرگز قبلاً حس نکرده بود."),
            StoryParagraph("And when he opened his eyes, when he returned to himself, when he saw his friend before him, he felt that he had received what he had been seeking all his life.", "و وقتی چشمانش را باز کرد، وقتی به خودش بازگشت، وقتی دوستش را پیش رویش دید، حس کرد آنچه تمام عمرش در جستجویش بود را دریافت کرده."),
            StoryParagraph("'Thank you,' he said, and his voice was full of tears, and his heart was full of gratitude. 'Thank you, my friend, for what you have given me.'", "گفت: «متشکرم.» و صدایش پر از اشک بود و قلبش پر از سپاس. «متشکرم، دوستم، برای آنچه به من دادی.»"),
            StoryParagraph("And Siddhartha smiled, the smile of a man who has found peace, the smile of a man who has become one with the world.", "و سیدارتا لبخند زد، لبخند مردی که آرامش یافته، لبخند مردی که با جهان یکی شده."),
            StoryParagraph("'The river has taught me everything,' he said, 'and the river has given me everything, and I am grateful for everything, and I am at peace.'", "گفت: «رود همه چیز به من آموخته و رود همه چیز به من داده و برای همه چیز سپاسگزارم و در صلحم.»"),
            StoryParagraph("And Govinda bowed, and Govinda left, and Govinda continued on his way, carrying with him the gift that his friend had given him, the gift of a moment of understanding.", "و گویندا تعظیم کرد و گویندا رفت و گویندا به راهش ادامه داد، با خود هدیه‌ای که دوستش داده بود حمل می‌کرد، هدیه لحظه‌ای از فهم."),
            StoryParagraph("And Siddhartha stayed by the river, where he belonged, where he had always belonged, where he would stay until the end of his days.", "و سیدارتا کنار رود ماند، همانجا که به آن تعلق داشت، همانجا که همیشه به آن تعلق داشت، همانجا که تا پایان روزهایش می‌ماند.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Siddhartha is a novel about a journey, but it is not a journey from one place to another; it is a journey inward, a journey toward the self, a journey toward enlightenment.", "سیدارتا رمانی است درباره سفری، اما سفری از جایی به جای دیگر نیست؛ سفری است به درون، سفری به سمت خود، سفری به سمت روشن‌ضمیری."),
            StoryParagraph("The novel was written by Hermann Hesse, a German-Swiss writer who was deeply influenced by Indian philosophy, particularly by Buddhism and Hinduism.", "رمان توسط هرمان هسه نوشته شده، نویسنده آلمانی-سوئیسی که عمیقاً تحت تأثیر فلسفه هندی، به‌ویژه بودیسم و هندوئیسم بود."),
            StoryParagraph("Hesse was himself a seeker, a man who struggled with depression, with alienation, with the search for meaning in a world that seemed to offer none.", "خود هسه جوینده‌ای بود، مردی که با افسردگی دست‌وپنجه نرم می‌کرد، با بیگانگی، با جستجوی معنا در جهانی که به نظر می‌رسید هیچ معنایی ارائه نمی‌دهد."),
            StoryParagraph("And so, in Siddhartha, he created a character who embodied his own search, his own questions, his own longing for understanding.", "و اینگونه، در سیدارتا، شخصیتی آفرید که جستجوی خودش را مجسم می‌کرد، پرسش‌های خودش، اشتیاق خودش برای فهم."),
            StoryParagraph("The novel is set in ancient India, in the time of the Buddha, but it is not a historical novel; it is a philosophical novel, a spiritual novel, a novel of ideas.", "رمان در هند باستان می‌گذرد، در زمان بودا، اما رمان تاریخی نیست؛ رمانی فلسفی است، رمانی روحانی، رمانی از ایده‌ها."),
            StoryParagraph("Siddhartha, the protagonist, is a Brahmin's son who leaves his home to seek enlightenment; he tries many paths, and he learns from many teachers, but he does not find what he is seeking until he stops seeking.", "سیدارتا، قهرمان، پسر برهمنی است که خانه‌اش را ترک می‌کند تا روشن‌ضمیری بجوید؛ راه‌های بسیاری را می‌آزماید و از معلمان بسیاری می‌آموزد، اما آنچه در جستجویش است را نمی‌یابد تا وقتی که دست از جستجو می‌کشد."),
            StoryParagraph("The novel is divided into two parts, and each part has its own theme; the first part is about the search for wisdom through external means, and the second part is about the discovery of wisdom through internal means.", "رمان به دو بخش تقسیم می‌شود و هر بخش مضمون خودش را دارد؛ بخش نخست درباره جستجوی خرد از طریق وسایل بیرونی است و بخش دوم درباره کشف خرد از طریق وسایل درونی."),
            StoryParagraph("In the first part, Siddhartha tries to find enlightenment by following the teachings of others: the Brahmins, the Samanas, the Buddha himself.", "در بخش نخست، سیدارتا تلاش می‌کند روشن‌ضمیری را با پیروی از تعالیم دیگران بیابد: برهمنان، ساماناها، خود بودا."),
            StoryParagraph("But none of these teachings satisfy him; each of them offers a partial truth, but none of them offers the whole truth; each of them points toward enlightenment, but none of them leads there.", "اما هیچ‌یک از این تعالیم راضی‌اش نمی‌کند؛ هر یک حقیقتی جزئی پیشنهاد می‌دهد اما هیچ‌یک حقیقت کامل را پیشنهاد نمی‌دهد؛ هر یک به سمت روشن‌ضمیری اشاره می‌کند اما هیچ‌یک آنجا نمی‌رساند."),
            StoryParagraph("So Siddhartha decides to find his own way, to learn from his own experience, to discover the truth for himself.", "پس سیدارتا تصمیم می‌گیرد راه خودش را بیابد، از تجربه خودش بیاموزد، حقیقت را برای خودش کشف کند."),
            StoryParagraph("In the second part, he enters the world, and he experiences everything that the world has to offer: wealth, pleasure, love, power.", "در بخش دوم، به جهان وارد می‌شود و هر چیزی که جهان پیشنهاد می‌دهد را تجربه می‌کند: ثروت، لذت، عشق، قدرت."),
            StoryParagraph("He becomes a merchant, and he becomes rich; he falls in love with Kamala, and he learns the art of love; he becomes a man of the world, and he learns the ways of the world.", "تاجر می‌شود و ثروتمند می‌شود؛ عاشق کامالا می‌شود و هنر عشق را می‌آموزد؛ مرد دنیا می‌شود و راه‌های دنیا را می‌آموزد."),
            StoryParagraph("But none of these experiences satisfy him either; they only distract him, only confuse him, only lead him further away from what he is seeking.", "اما هیچ‌یک از این تجربه‌ها هم راضی‌اش نمی‌کند؛ تنها منحرفش می‌کنند، گیجش می‌کنند، او را از آنچه در جستجویش است دورتر می‌برند."),
            StoryParagraph("And so, at last, he leaves the world behind, and he returns to the river, and he becomes a ferryman, and he learns from the river what no human teacher could teach him.", "و اینگونه، سرانجام، جهان را پشت سر می‌گذارد و به رود بازمی‌گردد و قایق‌ران می‌شود و از رود می‌آموزد آنچه هیچ معلم انسانی نمی‌توانست بیاموزد."),
            StoryParagraph("The river teaches him that all things are one, that all voices are one voice, that all beings are the same being; and in learning this, he attains enlightenment.", "رود به او می‌آموزد همه چیز یکی است، همه صداها یک صداست، همه موجودات همان یک موجودند؛ و در آموختن این، به روشن‌ضمیری می‌رسد."),
            StoryParagraph("The message of the novel is complex, but it can be summarized in a few key ideas.", "پیام رمان پیچیده است اما می‌توان آن را در چند ایده کلیدی خلاصه کرد."),
            StoryParagraph("First, wisdom cannot be taught; it can only be discovered. The teachings of others can point the way, but they cannot lead there; each being must find their own path.", "نخست، خرد را نمی‌توان آموخت؛ تنها می‌توان کشفش کرد. تعالیم دیگران می‌توانند راه را نشان دهند اما نمی‌توانند برسانند؛ هر موجودی باید راه خودش را بیابد."),
            StoryParagraph("Second, the world is both beautiful and terrible, and both aspects are necessary; to love the world, one must love it entirely, with all its pain and all its joy.", "دوم، جهان هم زیبا و هم هولناک است و هر دو جنبه ضروری‌اند؛ برای دوست داشتن جهان، باید کاملاً دوستش داشت، با تمام درد و تمام شادی‌اش."),
            StoryParagraph("Third, time is an illusion; the past and the future do not exist; only the present moment exists, and in the present moment, everything is already accomplished.", "سوم، زمان توهمی است؛ گذشته و آینده وجود ندارند؛ تنها لحظه حال وجود دارد و در لحظه حال، همه چیز از قبل محقق شده."),
            StoryParagraph("Fourth, love is the most important thing in the world; not romantic love, not personal love, but universal love, the love that embraces all beings, the love that sees the divine in everything.", "چهارم، عشق مهم‌ترین چیز در جهان است؛ نه عشق رمانتیک، نه عشق شخصی، بلکه عشق جهانی، عشقی که همه موجودات را در آغوش می‌گیرد، عشقی که الهی را در همه چیز می‌بیند."),
            StoryParagraph("Fifth, the goal of life is not to escape from the world, but to embrace it; not to transcend existence, but to fully live it; not to find peace elsewhere, but to find peace here, in this moment, in this life.", "پنجم، هدف زندگی فرار از جهان نیست، بلکه در آغوش گرفتنش است؛ فراتر رفتن از هستی نیست، بلکه کامل زیستنش است؛ یافتن آرامش در جایی دیگر نیست، بلکه یافتنش اینجا، در این لحظه، در این زندگی."),
            StoryParagraph("These ideas are not new; they can be found in many spiritual traditions, East and West alike.", "این ایده‌ها جدید نیستند؛ در بسیاری از سنت‌های روحانی، شرقی و غربی، یافت می‌شوند."),
            StoryParagraph("But Hesse presents them in a way that is fresh, that is personal, that is universal; he presents them not as doctrine but as experience, not as teaching but as life.", "اما هسه آن‌ها را به شیوه‌ای تازه ارائه می‌دهد، شخصی، جهانی؛ نه به‌عنوان عقیده بلکه به‌عنوان تجربه، نه به‌عنوان تعالیم بلکه به‌عنوان زندگی."),
            StoryParagraph("And this is what makes Siddhartha such a powerful novel: it does not tell us what to believe; it shows us what it means to seek, to struggle, to fail, and finally, to find.", "و این همان چیزی است که سیدارتا را رمانی اینقدر قدرتمند می‌کند: به ما نمی‌گوید چه باور کنیم؛ نشانمان می‌دهد معناي جستجو کردن چیست، کشمکش کردن، شکست خوردن و سرانجام، یافتن."),
            StoryParagraph("The novel has been read by millions of people around the world, and it has been translated into dozens of languages; it has been called a spiritual classic, a modern scripture, a guide to enlightenment.", "رمان توسط میلیون‌ها نفر در سراسر جهان خوانده شده و به ده‌ها زبان ترجمه شده؛ آن را کلاسیکی روحانی نامیده‌اند، کتاب مقدسی مدرن، راهنمایی به روشن‌ضمیری."),
            StoryParagraph("And yet, it is not a book of answers; it is a book of questions; it does not tell us what to do, but asks us to consider what we are doing, and why.", "و با این حال، کتاب پاسخ‌ها نیست؛ کتاب پرسش‌هاست؛ به ما نمی‌گوید چه بکنیم، بلکه از ما می‌پرسد چه می‌کنیم و چرا."),
            StoryParagraph("For in the end, the only true teacher is life itself; and the only true wisdom is the wisdom that we discover in the living of it.", "زیرا در پایان، تنها معلم راستین خود زندگی است؛ و تنها خرد راستین خردی است که در زیستنش کشف می‌کنیم."),
            StoryParagraph("And so Siddhartha's journey is our journey, and his search is our search, and his enlightenment is the enlightenment that each of us is called to find, in our own way, in our own time.", "و اینگونه سفر سیدارتا سفر ماست و جستجویش جستجوی ما و روشن‌ضمیری‌اش روشن‌ضمیری‌ای است که هر یک از ما خوانده شده‌ایم بیابیم، به شیوه خودمان، در زمان خودمان."),
            StoryParagraph("For we are all Siddhartha, seekers on a journey, wanderers in a world that is both beautiful and terrible, human beings who are called to discover, in the depths of our own being, the peace that passes all understanding.", "زیرا همه‌مان سیدارتاییم، جویندگانی در سفری، سرگردانانی در جهانی که هم زیبا و هم هولناک است، انسان‌هایی که خوانده شده‌ایم کشف کنیم، در اعماق وجود خودمان، آرامشی که فراتر از همه فهم است."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("And the eternal present, in which all things are already accomplished.", "و حال ابدی، که در آن همه چیز از قبل محقق شده.")
        )
    )
